CREATE TABLE push_subscription (id UUID PRIMARY KEY, technician_id UUID NOT NULL, token VARCHAR(512) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_push_subscription_technician FOREIGN KEY (technician_id) REFERENCES app_user (id) ON DELETE CASCADE, CONSTRAINT uk_push_subscription_token UNIQUE (token));
CREATE INDEX ix_push_subscription_technician_enabled ON push_subscription (technician_id, enabled);
CREATE TABLE push_notification_outbox (id UUID PRIMARY KEY, subscription_id UUID NOT NULL, inspection_id UUID NOT NULL, type VARCHAR(64) NOT NULL, title VARCHAR(255) NOT NULL, body VARCHAR(1000) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'QUEUED', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_push_outbox_subscription FOREIGN KEY (subscription_id) REFERENCES push_subscription (id) ON DELETE CASCADE, CONSTRAINT fk_push_outbox_inspection FOREIGN KEY (inspection_id) REFERENCES inspection (id) ON DELETE CASCADE, CONSTRAINT ck_push_outbox_status CHECK (status IN ('QUEUED', 'SENT', 'FAILED')));
